391	    /**
392	     * The owner's locality: the canonical region carried in the {@code <REGION>-<HASH8>}
393	     * customer code, i.e. the same region-and-hash identity used everywhere else. That
394	     * region was derived at creation by preferring the postcode range (NSW 2000-2099,
395	     * VIC 3000-3099, QLD 4000-4099), falling back to the fixed city-to-region table
396	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no
397	     * known range, or {@code "UNKNOWN"} otherwise. For an owner with no customer code the
398	     * region is derived directly from the stored postcode and city. Derived from stored
399	     * state, never persisted.
400	     */
401	    public String getLocality() {
402	        String region = CustomerCode.regionOf(this.customerCode);
403	        return region != null ? region : CityLocality.forPostcodeOrCity(this.postcode, this.city);
