408	     * via the fixed region-to-timezone table (NSW->Australia/Sydney,
409	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane), or {@code null} when the region
410	     * has no known timezone. Derived from stored state, never persisted.
411	     */
412	    public String getTimezone() {
413	        return RegionTimezone.forRegion(getLocality());
414	    }
415	
416	    /**
417	     * The owner's membership points, from 0 upwards: starts at 0, gains 2 when this owner
418	     * has an email address, gains 1 when this owner had no namesakes at creation
419	     * ({@code namesakeCount} is 0), gains 2 when this owner's household has 3 or more
420	     * members, and gains 3 once this owner's tenure spans at least one elapsed fiscal year.
421	     * A newly created owner has zero tenure, so it never earns those points at creation.
422	     * Derived from stored state, never persisted.
423	     */
424	    public int getMembershipPoints() {
425	        int points = 0;
426	        if (hasEmail()) {
427	            points += 2;
428	        }
429	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
430	            points += 1;
431	        }
432	        if (this.householdSize != null && this.householdSize >= 3) {
433	            points += 2;
434	        }
435	        if (getTenureFiscalYears() >= 1) {
436	            points += 3;
437	        }
438	        return points;
439	    }
440	
441	    /**
442	     * The owner's fiscal year: the {@code FY<YY>} label (fiscal year starting 1 July,
443	     * identified by its ending calendar year) of the {@code registrationDate}, or
444	     * {@code null} when no registration date is recorded. Derived from stored state, never
445	     * persisted.
446	     */
447	    public String getFiscalYear() {
448	        return this.registrationDate == null ? null : FiscalYear.labelOf(this.registrationDate);
449	    }
450	
451	    /**
452	     * The owner's membership level, from 1 to 4: derived from {@link #getMembershipPoints()}
453	     * as level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more, then capped at
454	     * the {@link #getMembershipLevelCap() membership level cap} when one applies. Derived from
455	     * stored state, never persisted.
456	     */
457	    public int getMembershipLevel() {
458	        int level = uncappedMembershipLevel();
459	        return this.membershipLevelCap == null ? level : Math.min(level, this.membershipLevelCap);
460	    }
461	
462	    private int uncappedMembershipLevel() {
463	        int points = getMembershipPoints();
464	        if (points <= 1) {
465	            return 1;
466	        }
467	        if (points <= 3) {
468	            return 2;
469	        }
470	        if (points <= 5) {
471	            return 3;
472	        }
473	        return 4;
474	    }
475	
476	    /**
477	     * The owner's tenure in elapsed fiscal years: the number of fiscal years (each
478	     * starting 1 July) between the {@code registrationDate} and the current server date, or
479	     * 0 when no registration date is recorded. Never negative in practice, since a future
480	     * registration date is rejected at creation.
481	     */
482	    private int getTenureFiscalYears() {
483	        if (this.registrationDate == null) {
484	            return 0;
485	        }
486	        return FiscalYear.elapsed(this.registrationDate, LocalDate.now());
487	    }
488	
489	    /**
490	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of
491	     * the {@code customerCode}. Derived from stored state, never persisted.
492	     */
493	    public int getCheckDigit() {
494	        return LuhnCheckDigit.of(this.customerCode);
495	    }
496	
497	    /**
498	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
499	     * present, otherwise {@code "PHONE"}. Derived from stored state, never persisted.
500	     */
501	    public String getContactPreference() {
502	        return hasEmail() ? "EMAIL" : "PHONE";
503	    }
504	
505	    /**
506	     * The owner's identity key: the 64-character lower-case SHA-256 hex of the normalized
507	     * telephone, the lower-cased email (or empty when absent) and the {@link Soundex Soundex}
508	     * code of the last name, joined by {@code '|'}. Two owners collide on this key only when
509	     * they share a telephone, an email and a phonetically-equal surname, so it is the single
510	     * fingerprint the create endpoint's duplicate check keys off. Derived from stored state,
511	     * never persisted.
512	     */
513	    public String getIdentityKey() {
514	        String telephonePart = this.telephone == null ? "" : this.telephone;
515	        String emailPart = hasEmail() ? this.email.toLowerCase(Locale.ROOT) : "";
516	        String namePart = Soundex.of(getLastName());
517	        return Sha256.lowerHex(telephonePart + "|" + emailPart + "|" + namePart);
518	    }
519	
520	    private boolean hasEmail() {
521	        return this.email != null && !this.email.isEmpty();
522	    }
523	
