536	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
537	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
538	        return Collections.unmodifiableList(sortedPets);
539	    }
