587	
588	            .append("id", this.getId())
589	            .append("new", this.isNew())
590	            .append("lastName", this.getLastName())
591	            .append("firstName", this.getFirstName())
592	            .append("address", this.address)
593	            .append("city", this.city)
594	            .append("telephone", this.telephone)
595	            .toString();
